/**
 * Get the slug for a specific blog post and locale
 */
export function getBlogSlugForLocale(blogId: string, locale: SupportedLocale): string | undefined {
  const config = blogPageSlugs.find(c => c.blogId === blogId);
  if (!config) return undefined;
  return config.slugs[locale] || config.slugs.en;
}

/**
 * Get the blog config from any slug (in any language)
 */
export function getBlogConfigBySlug(slug: string): { blogId: string; locale: SupportedLocale } | undefined {
  for (const config of blogPageSlugs) {
    for (const [locale, localeSlug] of Object.entries(config.slugs)) {
      if (localeSlug === slug) {
        return { blogId: config.blogId, locale: locale as SupportedLocale };
      }
    }
  }
  return undefined;
}

/**
 * Get all slugs for all locales (for generateStaticParams)
 */
export function getAllBlogPageSlugs(): { locale: SupportedLocale; slug: string }[] {
  const result: { locale: SupportedLocale; slug: string }[] = [];

  for (const config of blogPageSlugs) {
    for (const [locale, slug] of Object.entries(config.slugs)) {
      if (slug) {
        result.push({ locale: locale as SupportedLocale, slug });
      }
    }
  }

  return result;
}

/**
 * Get alternate language URLs for hreflang tags
 */
export function getBlogAlternateUrls(blogId: string, baseUrl: string = 'https://www.lessoncraftstudio.com'): Record<string, string> {
  const config = blogPageSlugs.find(c => c.blogId === blogId);
  if (!config) return {};

  const alternates: Record<string, string> = {};
  for (const [locale, slug] of Object.entries(config.slugs)) {
    if (slug) {
      const hreflangCode = getHreflangCode(locale);
      alternates[hreflangCode] = `${baseUrl}/${locale}/blog/${slug}`;
    }
  }

  if (alternates['en']) {
    alternates['x-default'] = alternates['en'];
  }

  return alternates;
}

/**
 * Check if a slug exists for a specific locale
 */
export function hasBlogPage(slug: string, locale: SupportedLocale): boolean {
  const config = getBlogConfigBySlug(slug);
  if (!config) return false;

  const blogConfig = blogPageSlugs.find(c => c.blogId === config.blogId);
  return blogConfig?.slugs[locale] === slug;
}
